    if h % 2 == 1 and len(set(grid[h // 2])) == 1 and grid[h // 2][0] != 0:
        mid = h // 2
        return [
            [2 if grid[r][c] != 0 and grid[mid + 1 + r][c] != 0 else 0
             for c in range(w)]
            for r in range(mid)
        ]

    mid = w // 2
    return [
        [2 if row[c] != 0 and row[mid + 1 + c] != 0 else 0
         for c in range(mid)]
        for row in grid
    ]
